const body = $input.first().json.body || $input.first().json;
const facturen = body.facturen || [];
const teVersturen = facturen.filter(f => f.versturen === true || f.versturen === 'true');

if (teVersturen.length === 0) {
  // Niets geselecteerd
  return [{ json: { skip: true, bericht: 'Geen facturen geselecteerd' } }];
}

if (teVersturen.length > 1) {
  // Meer dan 1 geselecteerd: alleen de eerste sturen, rest als melding
  const overige = teVersturen.slice(1).map(f => f.nr).join(', ');
  return [{ json: { invoice_number: teVersturen[0].nr, extra_melding: 'Let op: ' + overige + ' is nog niet verstuurd. Stuur per factuur 1 tegelijk.' } }];
}

return [{ json: { invoice_number: teVersturen[0].nr } }];

const inv = $('MySQL: Factuur details').first().json;
const items = $input.all().map(r => r.json);
return [{ json: {
  invoice_number: inv.invoice_number,
  invoice_date: inv.date,
  due_date: inv.due_date,
  subtotal: inv.subtotal,
  btw_total: inv.btw_total,
  total: inv.total,
  customer: {
    name: inv.customer_name, email: inv.customer_email,
    address: inv.address, postal_code: inv.postal_code,
    city: inv.city, country: inv.country,
    vat_number: inv.vat_number, kvk_number: inv.kvk_number
  },
  body: { project: inv.project || '', notities: inv.notes || '' },
  regels: items.map(i => ({
    omschrijving: i.description, aantal: i.quantity,
    prijs: i.unit_price, btw_tarief: i.btw_rate,
    bedrag: parseFloat(i.quantity) * parseFloat(i.unit_price)
  }))
}}];

const d = $node["Function: Data samenvoegen"].json;
const s = $json; // settings from DB
const bedrijfsnaam = s.bedrijfsnaam || 'Mijn Bedrijf';
const kvk = s.kvk || '';
const iban = s.iban || '';
const email = s.email || '';
const telefoon = s.telefoon || '';
const btw_nummer = s.btw_nummer || '';
const logo_url = s.logo_url || '';
const adres = s.adres || '';
const postcode = s.postcode || '';
const stad = s.stad || '';


function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function eur(n) {
  const v = parseFloat(n||0);
  return v === 0 ? '&euro;&nbsp;-' : '&euro;&nbsp;' + v.toFixed(2).replace('.',',');
}
function formatDate(s) {
  if (!s) return '';
  const d = new Date(s);
  return d.getUTCDate() + '-' + (d.getUTCMonth()+1) + '-' + d.getUTCFullYear();
}

const c = d.customer || {};
const regels = (d.regels || []).filter(r => r.omschrijving && parseFloat(r.prijs||0) > 0);
const body = d.body || {};
const project = body.project || d.notes || '';

let btwHoog = 0, btwLaag = 0;
regels.forEach(r => {
  const pct = parseFloat(r.btw_tarief || 0);
  const bedrag = parseFloat(r.bedrag || 0);
  if (pct >= 20) btwHoog += bedrag * pct / 100;
  else if (pct > 0) btwLaag += bedrag * pct / 100;
});

const projectRow = '';

const regelRows = regels.map(r => `
  <tr>
    <td style="text-align:center;padding:5px 8px;">${esc(r.aantal)}</td>
    <td style="padding:5px 8px;">${esc(r.omschrijving)}</td>
    <td style="text-align:right;padding:5px 8px;">${eur(r.prijs)}</td>
    <td style="text-align:center;padding:5px 8px;">${r.btw_tarief}%</td>
    <td style="text-align:right;padding:5px 8px;">${eur(r.bedrag)}</td>
  </tr>`).join('');

const filled = regels.length + (project ? 1 : 0);
const emptyCount = Math.max(0, 8 - filled);
const emptyRows = Array(emptyCount).fill('<tr style="height:24px;"><td></td><td></td><td></td><td></td><td></td></tr>').join('');

